# Run from the repository root: Rscript R/94_reproduce_from_public_data.R
# Optional stages: inputs, environment, windows, models, temporal, exports, figures, verify
# Reuses only checkpoints generated by this public-data pipeline.
.libPaths(c('.Rlib', .libPaths()))
args <- commandArgs(trailingOnly=TRUE)
stages <- if(length(args)) args else c('inputs','environment','windows','models','temporal','exports','figures','verify')
valid <- c('inputs','environment','windows','models','temporal','exports','figures','verify')
stopifnot(all(stages %in% valid))
if(any(stages %in% c('models','temporal','exports','verify'))) {
  stopifnot(requireNamespace('glmmTMB',quietly=TRUE),requireNamespace('MASS',quietly=TRUE))
  if(packageVersion('glmmTMB') < '1.1.14') stop('glmmTMB >= 1.1.14 is required')
}
output <- 'tables/reproduced'
dir.create(output,recursive=TRUE,showWarnings=FALSE)
Sys.setenv(WB_MODEL_DIR='models/within_between_20261026',WB_OUTPUT_SUFFIX='_reproduced',
           WB_EXPORT_DIR='tables/within_between_20261026_reproduced',
           TEMPORAL_MODEL_DIR='models/reproduced_temporal',
           TEMPORAL_EXPORT_DIR='tables/reproduced/temporal',
           JOINT_YEAR_EXPORT_DIR='tables/reproduced/joint_calendar_year')
Sys.unsetenv('WB_TRAITS')
run <- function(file) {
  cat('\nRUN ',file,'\n',sep='');flush.console()
  env <- new.env(parent=globalenv())
  source(file,local=env)
  invisible(env)
}
if('inputs' %in% stages) {
  run('R/browser/01_weather_inputs.R')
  run('R/95_validate_public_model_data.R')
  env <- run('R/03_predictor_diagnostics.R')
  env$run_predictor_diagnostics('data_derived/analysis/clutch_model_data.csv',
                                'data_derived/analysis/fledging_model_data.csv')
}
if('environment' %in% stages) {
  env <- run('R/browser/04_environment_model.R')
  saveRDS(env$fit,file.path(output,'environment_fit.rds'))
  se<-sqrt(diag(solve(env$fit$hessian)))
  write.csv(data.frame(term=c('mean_intercept','warming_per_decade','log_SD_intercept','log_SD_per_decade'),
    estimate=env$fit$par,lower=env$fit$par-qnorm(.975)*se,upper=env$fit$par+qnorm(.975)*se),
    file.path(output,'environment_coefficients.csv'),row.names=FALSE)
  capture.output(print(env$fit$par),file=file.path(output,'environment_summary.txt'))
}
if('windows' %in% stages) {
  env <- run('R/browser/02_window_search.R')
  write.csv(env$answer,file.path(output,'selected_window.csv'),row.names=FALSE)
  write.csv(data.frame(delta_AICc=env$null),file.path(output,'fresh_randomised_searches.csv'),row.names=FALSE)
}
if('models' %in% stages) {
  env <- run('R/90_fit_temperature_within_between.R')
  env$run_within_between('data_derived/analysis/clutch_model_data.csv',
                         'data_derived/analysis/fledging_model_data.csv')
  run('R/97_fit_poisson_comparator.R')
}
if('temporal' %in% stages) run('R/83_fit_temporal_without_temperature.R')
if('exports' %in% stages) {
  run('R/96_export_baseline_predictions.R')
  run('R/98_baseline_simulation_checks.R')
  run('R/91_export_temperature_within_between.R')
  run('R/93_export_joint_calendar_year.R')
  run('R/84_export_temporal_without_temperature.R')
}
if('figures' %in% stages) run('R/99_plot_reproduced_results.R')
if('verify' %in% stages) {
  ref <- read.csv('tables/within_between_20261026/fixed_effects.csv')
  new <- read.csv('tables/within_between_20261026_reproduced/fixed_effects.csv')
  compare <- merge(ref,new,by=c('trait','model','component','term'),suffixes=c('_published','_reproduced'))
  stopifnot(nrow(compare)==nrow(ref),nrow(new)==nrow(ref))
  compare$absolute_difference <- abs(compare$estimate_published-compare$estimate_reproduced)
  write.csv(compare,file.path(output,'coefficient_comparison.csv'),row.names=FALSE)
  stopifnot(max(compare$absolute_difference)<.001)
  cat('Largest coefficient difference:',max(compare$absolute_difference),'\n')
  # Temporal fixed effects, using only models without temperature.
  ref <- read.csv('tables/temporal_models_20261022/fixed_effects.csv')
  new <- subset(read.csv('models/reproduced_temporal/fixed_effects.csv'),model=='without_temperature')
  z <- merge(ref,new,by=c('trait','component','term'),suffixes=c('_published','_reproduced'))
  stopifnot(nrow(z)==nrow(ref),max(abs(z$estimate_published-z$estimate_reproduced))<.001)
  write.csv(z,file.path(output,'temporal_coefficient_comparison.csv'),row.names=FALSE)
  summary_dir<-file.path(output,'model_summaries')
  dir.create(summary_dir,recursive=TRUE,showWarnings=FALSE)
  for(trait in c('clutch','fledging')) {
    for(kind in c('baseline','within_between')) {
      m<-readRDS(file.path('models/within_between_20261026',paste0(trait,'_',kind,'_selected.rds')))
      capture.output(summary(m),file=file.path(summary_dir,paste0(trait,'_',kind,'.txt')))
    }
    m<-readRDS(file.path('models/reproduced_temporal',paste0(trait,'_selected.rds')))
    capture.output(summary(m),file=file.path(summary_dir,paste0(trait,'_without_temperature.txt')))
  }
}
capture.output(sessionInfo(),file=file.path(output,'session_info.txt'))
cat('Requested stages completed. Published numerical exports were not overwritten.\n')
